inputs = ['xdazxa', 'fhfbb', 'jgijw', 'zvfdbi', 'zz']
outputs = ['xdazxa', 'fhfwccwcc', 'jgijw', 'zvfdwcci', 'zz']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Let's find the exact differences
        diff_pos = []
        for j, (c1, c2) in enumerate(zip(inp, outp)):
            if c1 != c2:
                diff_pos.append((j, c1, c2))

        # Handle cases where strings have different lengths
        if len(inp) != len(outp):
            max_len = max(len(inp), len(outp))
            for j in range(max_len):
                c1 = inp[j] if j < len(inp) else None
                c2 = outp[j] if j < len(outp) else None
                if c1 != c2:
                    diff_pos.append((j, c1, c2))

        print(f"  Differences at positions: {diff_pos}")

# Let's also look at the full context of the changes
print("\nAnalyzing differences:")
for idx, inp, outp in [(1, 'fhfbb', 'fhfwccwcc'), (3, 'zvfdbi', 'zvfdwcci')]:
    print(f"From '{inp}' to '{outp}':")
    # Find all differences
